import requests
import json

class KnowledgePortalMCP:
    def __init__(self, api_url, api_key):
        self.api_url = api_url
        self.api_key = api_key
        self.headers = {
            'Content-Type': 'application/json',
            'X-API-Key': api_key
        }

    def call_tool(self, tool_name, **arguments):
        payload = {
            'jsonrpc': '2.0',
            'id': 1,
            'method': 'tools/call',
            'params': {
                'name': tool_name,
                'arguments': arguments
            }
        }
        response = requests.post(
            f'{self.api_url}/mcp',
            json=payload,
            headers=self.headers
        )
        return response.json()

    def search_articles(self, query, limit=20, tags=None):
        return self.call_tool(
            'searchArticles',
            query=query,
            limit=limit,
            tags=tags
        )

    def get_article(self, id_or_slug):
        return self.call_tool('getArticle', idOrSlug=id_or_slug)

