interface McpRequest {
  jsonrpc: '2.0';
  id: number;
  method: string;
  params: {
    name: string;
    arguments: Record<string, any>;
  };
}

interface SearchArticlesArgs {
  query: string;
  limit?: number;
  tags?: string;
  authors?: string;
  contentType?: string;
}

class KnowledgePortalMCP {
  constructor(
    private apiUrl: string,
    private apiKey: string
  ) {}

  async callTool<T = any>(toolName: string, args: Record<string, any>): Promise<T> {
    const payload: McpRequest = {
      jsonrpc: '2.0',
      id: 1,
      method: 'tools/call',
      params: {
        name: toolName,
        arguments: args
      }
    };

    const response = await fetch(`${this.apiUrl}/mcp`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': this.apiKey
      },
      body: JSON.stringify(payload)
    });

    return response.json() as Promise<T>;
  }

  searchArticles(args: SearchArticlesArgs) {
    return this.callTool('searchArticles', args);
  }

  getArticle(idOrSlug: string) {
    return this.callTool('getArticle', { idOrSlug });
  }
}

