$ApiUrl = '[api-url]'
$ApiKey = 'kp_your_api_key_here'

function Invoke-McpTool {
    param(
        [string]$ToolName,
        [hashtable]$Arguments
    )

    $payload = @{
        jsonrpc = '2.0'
        id = 1
        method = 'tools/call'
        params = @{
            name = $ToolName
            arguments = $Arguments
        }
    } | ConvertTo-Json -Depth 10

    $response = Invoke-RestMethod -Uri "$ApiUrl/mcp" `
        -Method Post `
        -Headers @{
            'Content-Type' = 'application/json'
            'X-API-Key' = $ApiKey
        } `
        -Body $payload

    return $response
}

